insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('mat-t01','matematica','Trigonometria no triângulo retângulo','treino','A palavra "trigonometria" junta três partes gregas. O que ela significa?','["Estudo dos números primos", "Medida dos ângulos (e lados) do triângulo", "Medida de círculos e esferas", "Cálculo de áreas de quadrados"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t02','matematica','Trigonometria no triângulo retângulo','treino','Num triângulo retângulo, o lado que fica de frente para o ângulo reto chama-se:','["Cateto adjacente", "Hipotenusa", "Cateto oposto", "Bissetriz"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t03','matematica','Trigonometria no triângulo retângulo','treino','Qual é SEMPRE o maior lado de um triângulo retângulo?','["O cateto oposto ao menor ângulo", "O cateto adjacente ao maior ângulo agudo", "Depende do triângulo: pode ser qualquer lado", "A hipotenusa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t04','matematica','Trigonometria no triângulo retângulo','treino','No triângulo ABC, o ângulo reto está em A. Qual lado é o cateto OPOSTO ao ângulo B?','["AC", "AB", "BC", "Nenhum: o ângulo B não tem cateto oposto"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t05','matematica','Trigonometria no triângulo retângulo','treino','Os catetos de um triângulo retângulo medem 9 cm e 12 cm. Quanto mede a hipotenusa?','["21 cm", "13 cm", "10,5 cm", "15 cm"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t06','matematica','Trigonometria no triângulo retângulo','treino','Num triângulo retângulo, a hipotenusa mede 13 m e um cateto mede 5 m. Quanto mede o outro cateto?','["8 m", "12 m", "18 m", "14 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t07','matematica','Trigonometria no triângulo retângulo','treino','Os dois ângulos agudos de um triângulo retângulo, somados, dão:','["90°", "180°", "60°", "45°"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t08','matematica','Trigonometria no triângulo retângulo','treino','Num triângulo retângulo, um dos ângulos agudos mede 28°. Quanto mede o outro ângulo agudo?','["152°", "72°", "62°", "28°"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t09','matematica','Razões trigonométricas','treino','Num triângulo retângulo, o SENO de um ângulo agudo é:','["cateto adjacente ÷ hipotenusa", "cateto oposto ÷ hipotenusa", "cateto oposto ÷ cateto adjacente", "hipotenusa ÷ cateto oposto"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t10','matematica','Razões trigonométricas','treino','O COSSENO de um ângulo agudo é a razão entre:','["o cateto oposto e a hipotenusa", "o cateto oposto e o cateto adjacente", "a hipotenusa e o cateto adjacente", "o cateto adjacente e a hipotenusa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t11','matematica','Razões trigonométricas','treino','A TANGENTE de um ângulo agudo é a razão entre:','["o cateto adjacente e o cateto oposto", "o cateto oposto e a hipotenusa", "o cateto oposto e o cateto adjacente", "a hipotenusa e o cateto adjacente"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t12','matematica','Razões trigonométricas','treino','Um triângulo retângulo tem catetos 8 e 15 e hipotenusa 17. Para o ângulo α, que fica de frente para o cateto 8, quanto vale sen α?','["8/17", "15/17", "8/15", "17/8"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t13','matematica','Razões trigonométricas','treino','Um triângulo retângulo tem catetos 8 e 15 e hipotenusa 17. Para o ângulo α, que fica de frente para o cateto 8, quanto vale tg α?','["15/8", "8/17", "15/17", "8/15"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t14','matematica','Razões trigonométricas','treino','Um triângulo retângulo tem catetos 7 e 24 e hipotenusa 25. O ângulo β fica de frente para o cateto 24. Quanto vale cos β?','["24/25", "7/24", "7/25", "24/7"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t15','matematica','Razões trigonométricas','treino','α e β são os dois ângulos agudos do mesmo triângulo retângulo. Então sen α é igual a:','["sen β", "tg β", "1 ÷ sen β", "cos β"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t16','matematica','Razões trigonométricas','treino','Use: sen 37° ≈ 0,60; cos 37° ≈ 0,80; tg 37° ≈ 0,75. Num triângulo retângulo, a hipotenusa mede 20 cm e um ângulo agudo mede 37°. Quanto mede o cateto OPOSTO a esse ângulo?','["16 cm", "12 cm", "15 cm", "33,3 cm"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t17','matematica','Razões trigonométricas','treino','Num triângulo retângulo, sen α = 0,6 e a hipotenusa mede 15 cm. Quanto mede o cateto ADJACENTE a α?','["9 cm", "6 cm", "12 cm", "25 cm"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t18','matematica','Razões trigonométricas','treino','Qual destas razões trigonométricas de um ângulo agudo pode dar um valor MAIOR que 1?','["Seno", "Cosseno", "Nenhuma delas", "Tangente"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t19','matematica','Ângulos notáveis','treino','Quanto vale sen 30°?','["1/2", "√3/2", "√2/2", "√3/3"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t20','matematica','Ângulos notáveis','treino','Quanto vale cos 60°?','["1/2", "√3/2", "√3", "1"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t21','matematica','Ângulos notáveis','treino','Quanto vale tg 45°?','["√2/2", "0", "1", "√3"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t22','matematica','Ângulos notáveis','treino','Quanto vale tg 60°?','["√3/3", "√3", "1/2", "√3/2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t23','matematica','Ângulos notáveis','treino','Qual valor é, ao mesmo tempo, igual a sen 45° e a cos 45°?','["√2/2", "1/2", "√3/2", "1"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t24','matematica','Ângulos notáveis','treino','Quanto vale tg 30°?','["√3", "√3/3", "1/2", "√2/2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t25','matematica','Ângulos notáveis','treino','Calcule sen 30° + cos 60°.','["1", "1/2", "√3", "0"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t26','matematica','Ângulos notáveis','treino','Calcule (sen 60°)² + (cos 60°)².','["1/2", "3/4", "(1 + √3)/2", "1"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t27','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','Uma escada de 5 m está encostada num muro, com o pé a 3 m do muro. Até que altura do muro a escada chega?','["2 m", "8 m", "5,8 m", "4 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t28','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','A tela de uma TV é um retângulo de 48 cm de largura e 36 cm de altura. Quanto mede a diagonal da tela?','["84 cm", "60 cm", "42 cm", "70 cm"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t29','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','Uma rampa sobe 1 m de altura enquanto avança 4 m na horizontal. Quanto vale a tangente do ângulo de inclinação da rampa?','["4", "0,25", "0,2", "0,75"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t30','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','Um poste em pé, a sombra dele no chão e o raio de sol que vai do topo do poste até a ponta da sombra formam um triângulo retângulo. Qual lado é a hipotenusa?','["O poste", "A sombra", "O raio de sol, do topo do poste até a ponta da sombra", "Nenhum: esse triângulo não é retângulo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t31','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','Um avião sobe em linha reta. Depois de percorrer 2 000 m nessa linha, está a 700 m de altura. A conta 700 ÷ 2 000 = 0,35 dá qual razão do ângulo de subida?','["Cosseno", "Tangente", "Nenhuma razão trigonométrica", "Seno"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t32','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','Um terreno retangular mede 60 m por 80 m. Em vez de contornar dois lados, João atravessa pela diagonal. Quantos metros ele economiza?','["100 m", "40 m", "140 m", "20 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t33','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','Para que serve o teodolito?','["Medir a temperatura do ar", "Pesar objetos grandes", "Medir ângulos horizontais e verticais", "Medir o volume de líquidos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t34','matematica','Situações-problema: trigonometria no triângulo retângulo','treino','Uma pipa está presa por 50 m de linha bem esticada, e está 30 m acima da mão do menino. Qual é a distância horizontal entre a mão do menino e o ponto embaixo da pipa?','["40 m", "20 m", "80 m", "58 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t35','matematica','Situações-problema: razões trigonométricas','treino','Use: sen 20° ≈ 0,34; cos 20° ≈ 0,94; tg 20° ≈ 0,36. Uma rampa de 10 m de comprimento faz 20° com o chão. A que altura ela chega?','["9,4 m", "3,6 m", "3,4 m", "29,4 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t36','matematica','Situações-problema: razões trigonométricas','treino','Use: sen 40° ≈ 0,64; cos 40° ≈ 0,77; tg 40° ≈ 0,84. A 30 m da base de um prédio, uma pessoa vê o topo sob um ângulo de 40° com o chão. Qual é a altura aproximada do prédio? (Despreze a altura da pessoa.)','["19,2 m", "23,1 m", "25,2 m", "35,7 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t37','matematica','Situações-problema: razões trigonométricas','treino','Use: sen 35° ≈ 0,57; cos 35° ≈ 0,82; tg 35° ≈ 0,70. A rampa de um escorregador mede 4 m e faz 35° com o chão. Qual distância no chão a rampa ocupa (do começo ao fim, na horizontal)?','["3,28 m", "2,28 m", "2,80 m", "4,88 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t38','matematica','Situações-problema: razões trigonométricas','treino','Use: sen 50° ≈ 0,77; cos 50° ≈ 0,64; tg 50° ≈ 1,19. Um cabo de aço vai do topo de uma torre de 12 m até o chão e forma 50° com o chão. Qual é o comprimento aproximado do cabo?','["9,2 m", "18,8 m", "10,1 m", "15,6 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t39','matematica','Situações-problema: razões trigonométricas','treino','Use: sen 25° ≈ 0,42; cos 25° ≈ 0,91. Um barco navega 100 km em linha reta, numa direção que faz 25° com a direção leste (subindo para o norte). Quantos quilômetros ele avançou para o norte?','["91 km", "42 km", "47 km", "25 km"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t40','matematica','Situações-problema: razões trigonométricas','treino','Use: sen 70° ≈ 0,94; cos 70° ≈ 0,34; tg 70° ≈ 2,75. Uma escada encostada na parede forma 70° com o chão, e o pé dela está a 1,2 m da parede. Quanto mede a escada, aproximadamente?','["1,1 m", "3,5 m", "3,3 m", "0,4 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t41','matematica','Situações-problema: razões trigonométricas','treino','Use a tabela: tg 5° ≈ 0,09; tg 9° ≈ 0,16; tg 12° ≈ 0,21; tg 15° ≈ 0,27. Um telhado sobe 15 cm a cada 100 cm na horizontal. O ângulo de inclinação do telhado está mais próximo de:','["9°", "15°", "5°", "12°"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t42','matematica','Situações-problema: razões trigonométricas','treino','Use: tg 35° ≈ 0,70. Uma pessoa, com os olhos a 1,5 m do chão, está a 20 m de uma árvore e vê o topo dela sob um ângulo de 35° (medido na altura dos olhos). Qual é a altura da árvore?','["14 m", "15,5 m", "12,5 m", "29,5 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t43','matematica','Situações-problema: ângulos notáveis','treino','Uma rampa de 8 m de comprimento faz 30° com o chão. A que altura ela chega?','["4 m", "4√3 m", "16 m", "2 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t44','matematica','Situações-problema: ângulos notáveis','treino','Uma pessoa a 10 m de um poste vê o topo dele sob 45°. Qual é a altura do poste? (Despreze a altura da pessoa.)','["10 m", "5 m", "10√2 m", "20 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t45','matematica','Situações-problema: ângulos notáveis','treino','Use √3 ≈ 1,73. Um fio esticado de 12 m vai do topo de um mastro até o chão e forma 60° com o chão. Qual é a altura aproximada do mastro?','["6 m", "20,8 m", "10,4 m", "6,9 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t46','matematica','Situações-problema: ângulos notáveis','treino','Uma criança solta pipa com 40 m de linha esticada, que forma 30° com o chão. A que altura está a pipa? (Despreze a altura da criança.)','["34,6 m", "80 m", "20 m", "23,1 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t47','matematica','Situações-problema: ângulos notáveis','treino','Use √3 ≈ 1,73. De um ponto P no chão, a 30 m da base de um prédio, vê-se o topo sob 60°. Qual é a altura aproximada do prédio?','["51,9 m", "17,3 m", "15 m", "60 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t48','matematica','Situações-problema: ângulos notáveis','treino','Uma escada de 6 m está encostada na parede e forma 60° com o chão. A que distância da parede está o pé da escada?','["3√3 m", "6√3 m", "12 m", "3 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t49','matematica','Situações-problema: ângulos notáveis','treino','Um quadrado tem lado de 5 cm. Quanto mede a diagonal?','["10 cm", "5√3 cm", "5√2 cm", "25 cm"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-t50','matematica','Situações-problema: ângulos notáveis','treino','Use √3 ≈ 1,73. Um avião decola com ângulo constante de 30° e percorre 3 km em linha reta. Quanto ele subiu e quanto andou na horizontal?','["Subiu cerca de 2,6 km e andou 1,5 km na horizontal", "Subiu 1,5 km e andou 3 km na horizontal", "Subiu 1,73 km e andou 1,5 km na horizontal", "Subiu 1,5 km e andou cerca de 2,6 km na horizontal"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p01','matematica','Trigonometria no triângulo retângulo','prova','Os catetos de um triângulo retângulo medem 6 cm e 8 cm. Quanto mede a hipotenusa?','["14 cm", "10 cm", "7 cm", "12 cm"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p02','matematica','Trigonometria no triângulo retângulo','prova','No triângulo MNP, o ângulo reto está no vértice P. Qual lado é a hipotenusa?','["MP", "MN", "NP", "Nenhum: a hipotenusa é o próprio ângulo P"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p03','matematica','Razões trigonométricas','prova','Num triângulo retângulo, a hipotenusa mede 10, o cateto oposto a α mede 6 e o cateto adjacente a α mede 8. Quanto vale cos α?','["0,6", "0,75", "0,8", "1,33"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p04','matematica','Razões trigonométricas','prova','Num triângulo retângulo de hipotenusa 25 cm, sen α = 0,8. Quanto mede o cateto oposto a α?','["15 cm", "31,25 cm", "5 cm", "20 cm"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p05','matematica','Ângulos notáveis','prova','Qual igualdade é verdadeira?','["sen 30° = cos 60°", "sen 30° = sen 60°", "tg 30° = tg 60°", "cos 45° = tg 45°"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p06','matematica','Ângulos notáveis','prova','Quanto vale cos 30°?','["√3/2", "1/2", "√3", "√2/2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p07','matematica','Situações-problema: trigonometria no triângulo retângulo','prova','Um portão retangular tem 1,2 m de largura e 1,6 m de altura. Vai receber uma barra de reforço na diagonal. Quanto mede essa barra?','["2 m", "2,8 m", "1,4 m", "2,4 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p08','matematica','Situações-problema: trigonometria no triângulo retângulo','prova','Uma escada encostada num muro forma, com o muro e o chão, um triângulo retângulo. Nesse triângulo, a escada é:','["Um cateto, sempre", "O menor lado", "O lado de frente para o menor ângulo", "A hipotenusa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p09','matematica','Situações-problema: razões trigonométricas','prova','Use: sen 20° ≈ 0,34; cos 20° ≈ 0,94; tg 20° ≈ 0,36. Um teleférico sobe por um cabo reto de 500 m que faz 20° com a horizontal. Quantos metros ele sobe na vertical?','["470 m", "180 m", "170 m", "147 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p10','matematica','Situações-problema: razões trigonométricas','prova','Use: sen 50° ≈ 0,77; cos 50° ≈ 0,64; tg 50° ≈ 1,19. A 50 m de uma torre, vê-se o topo sob 50°. Qual é a altura aproximada da torre? (Despreze a altura de quem observa.)','["38,5 m", "59,5 m", "42,0 m", "64,9 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p11','matematica','Situações-problema: ângulos notáveis','prova','Use √2 ≈ 1,41. A rampa de um escorregador mede 5 m e forma 45° com o chão. Qual é a altura aproximada do escorregador?','["5 m", "7,1 m", "2,5 m", "3,5 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mat-p12','matematica','Situações-problema: ângulos notáveis','prova','Use √3 ≈ 1,73. De um ponto no chão, a 20 m da base de um prédio, vê-se o topo sob 30°. Qual é a altura aproximada do prédio?','["10 m", "34,6 m", "11,5 m", "17,3 m"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf');
insert into gabarito (questao_id,correta,explicacao) values
  ('mat-t01',1,'TRI = três, GONO = ângulos, METRIA = medida: medidas ligadas ao triângulo.'),
  ('mat-t02',1,'O lado oposto ao ângulo de 90° é a hipotenusa. Os outros dois lados são os catetos.'),
  ('mat-t03',3,'A hipotenusa fica de frente para o maior ângulo (90°), por isso é sempre o maior lado.'),
  ('mat-t04',0,'O cateto oposto a B é o lado que não encosta em B: AC. AB encosta em B (adjacente) e BC é a hipotenusa.'),
  ('mat-t05',3,'Pitágoras: h² = 9² + 12² = 81 + 144 = 225, então h = 15 cm.'),
  ('mat-t06',1,'13² = 5² + x² → 169 = 25 + x² → x² = 144 → x = 12 m.'),
  ('mat-t07',0,'A soma dos ângulos de um triângulo é 180°. Tirando o reto (90°), sobram 90° para os dois agudos (são complementares).'),
  ('mat-t08',2,'Os agudos somam 90°: 90° − 28° = 62°.'),
  ('mat-t09',1,'sen = CO/H. Para lembrar: "SOH" (Seno = Oposto sobre Hipotenusa).'),
  ('mat-t10',3,'cos = CA/H ("CAH": Cosseno = Adjacente sobre Hipotenusa).'),
  ('mat-t11',2,'tg = CO/CA ("TOA": Tangente = Oposto sobre Adjacente).'),
  ('mat-t12',0,'sen α = cateto oposto ÷ hipotenusa = 8/17.'),
  ('mat-t13',3,'tg α = cateto oposto ÷ cateto adjacente = 8/15.'),
  ('mat-t14',2,'Se β fica de frente para o 24, o cateto adjacente a β é o 7. cos β = 7/25.'),
  ('mat-t15',3,'O cateto oposto a α é o cateto adjacente a β. Por isso sen α = cos β (os ângulos são complementares).'),
  ('mat-t16',1,'sen 37° = x/20 → x = 20 · 0,60 = 12 cm. (16 cm seria o cateto adjacente, com o cosseno.)'),
  ('mat-t17',2,'Cateto oposto = 15 · 0,6 = 9 cm. Por Pitágoras: 15² = 9² + x² → 225 = 81 + x² → x² = 144 → x = 12 cm.'),
  ('mat-t18',3,'Seno e cosseno dividem um cateto pela hipotenusa (o maior lado), então ficam menores que 1. A tangente divide um cateto pelo outro e pode passar de 1 (ex.: tg 60° ≈ 1,73).'),
  ('mat-t19',0,'sen 30° = 1/2. Dica: sen 30°, sen 45°, sen 60° = 1/2, √2/2, √3/2.'),
  ('mat-t20',0,'cos 60° = 1/2 (é igual ao sen 30°, porque 30° e 60° são complementares).'),
  ('mat-t21',2,'Com 45°, os dois catetos são iguais, então tg 45° = cateto ÷ mesmo cateto = 1.'),
  ('mat-t22',1,'tg 60° = sen 60° ÷ cos 60° = (√3/2) ÷ (1/2) = √3.'),
  ('mat-t23',0,'sen 45° = cos 45° = √2/2.'),
  ('mat-t24',1,'tg 30° = (1/2) ÷ (√3/2) = 1/√3 = √3/3.'),
  ('mat-t25',0,'sen 30° = 1/2 e cos 60° = 1/2. Somando: 1/2 + 1/2 = 1.'),
  ('mat-t26',3,'(√3/2)² + (1/2)² = 3/4 + 1/4 = 1. Isso vale para qualquer ângulo: sen² + cos² = 1.'),
  ('mat-t27',3,'A escada é a hipotenusa: 5² = 3² + h² → 25 = 9 + h² → h² = 16 → h = 4 m.'),
  ('mat-t28',1,'d² = 48² + 36² = 2304 + 1296 = 3600 → d = 60 cm.'),
  ('mat-t29',1,'tg = cateto oposto (altura) ÷ cateto adjacente (horizontal) = 1 ÷ 4 = 0,25.'),
  ('mat-t30',2,'O ângulo reto fica entre o poste e o chão. O lado de frente para ele é o raio de sol: a hipotenusa.'),
  ('mat-t31',3,'A altura é o cateto oposto ao ângulo de subida e o caminho percorrido é a hipotenusa: oposto ÷ hipotenusa = seno.'),
  ('mat-t32',1,'Diagonal: d² = 60² + 80² = 3600 + 6400 = 10000 → d = 100 m. Pelos lados: 60 + 80 = 140 m. Economia: 140 − 100 = 40 m.'),
  ('mat-t33',2,'O teodolito é o instrumento de precisão usado hoje (por exemplo, em obras) para medir ângulos. Antigamente, os navegadores usavam o astrolábio.'),
  ('mat-t34',0,'A linha é a hipotenusa: 50² = 30² + x² → 2500 = 900 + x² → x² = 1600 → x = 40 m.'),
  ('mat-t35',2,'A rampa é a hipotenusa e a altura é o cateto oposto: h = 10 · sen 20° = 10 · 0,34 = 3,4 m.'),
  ('mat-t36',2,'Temos o cateto adjacente (30 m) e queremos o oposto (altura): tg 40° = h/30 → h = 30 · 0,84 = 25,2 m.'),
  ('mat-t37',0,'A rampa é a hipotenusa e a distância no chão é o cateto adjacente: x = 4 · cos 35° = 4 · 0,82 = 3,28 m.'),
  ('mat-t38',3,'A torre é o cateto oposto ao ângulo de 50° e o cabo é a hipotenusa: sen 50° = 12/c → c = 12 ÷ 0,77 ≈ 15,6 m.'),
  ('mat-t39',1,'O caminho é a hipotenusa e o avanço para o norte é o cateto oposto ao ângulo de 25°: 100 · 0,42 = 42 km.'),
  ('mat-t40',1,'A distância até a parede é o cateto adjacente e a escada é a hipotenusa: cos 70° = 1,2/e → e = 1,2 ÷ 0,34 ≈ 3,5 m.'),
  ('mat-t41',0,'tg = 15 ÷ 100 = 0,15. Na tabela, o valor mais próximo de 0,15 é 0,16, que é a tangente de 9°.'),
  ('mat-t42',1,'Da altura dos olhos até o topo: 20 · 0,70 = 14 m. Somando a altura dos olhos: 14 + 1,5 = 15,5 m.'),
  ('mat-t43',0,'h = 8 · sen 30° = 8 · 1/2 = 4 m.'),
  ('mat-t44',0,'tg 45° = h/10 e tg 45° = 1, então h = 10 m. Com 45°, a altura é igual à distância.'),
  ('mat-t45',2,'h = 12 · sen 60° = 12 · √3/2 = 6√3 ≈ 6 · 1,73 ≈ 10,4 m.'),
  ('mat-t46',2,'h = 40 · sen 30° = 40 · 1/2 = 20 m.'),
  ('mat-t47',0,'tg 60° = h/30 → h = 30√3 ≈ 30 · 1,73 = 51,9 m.'),
  ('mat-t48',3,'A distância até a parede é o cateto adjacente ao ângulo de 60°: 6 · cos 60° = 6 · 1/2 = 3 m.'),
  ('mat-t49',2,'A diagonal forma 45° com os lados: cos 45° = 5/d → √2/2 = 5/d → d = 10/√2 = 5√2 cm. (Por Pitágoras também: d² = 25 + 25 = 50.)'),
  ('mat-t50',3,'Altura = 3 · sen 30° = 1,5 km. Horizontal = 3 · cos 30° = 3 · √3/2 ≈ 2,6 km.'),
  ('mat-p01',1,'h² = 6² + 8² = 36 + 64 = 100 → h = 10 cm.'),
  ('mat-p02',1,'A hipotenusa é o lado de frente para o ângulo reto (P): o lado que liga M e N.'),
  ('mat-p03',2,'cos α = adjacente ÷ hipotenusa = 8/10 = 0,8.'),
  ('mat-p04',3,'sen α = x/25 → x = 25 · 0,8 = 20 cm.'),
  ('mat-p05',0,'sen 30° = 1/2 e cos 60° = 1/2. Ângulos complementares trocam seno e cosseno.'),
  ('mat-p06',0,'cos 30° = √3/2 (igual ao sen 60°).'),
  ('mat-p07',0,'d² = 1,2² + 1,6² = 1,44 + 2,56 = 4 → d = 2 m.'),
  ('mat-p08',3,'O ângulo reto fica entre o muro e o chão. A escada fica de frente para ele: é a hipotenusa.'),
  ('mat-p09',2,'O cabo é a hipotenusa e a subida é o cateto oposto: 500 · 0,34 = 170 m.'),
